import { BlockId, EquipmentBonuses, ItemDef, Rarity } from '@/types/game';

const item = (partial: Partial<ItemDef> & Pick<ItemDef, 'id' | 'name' | 'category'>): ItemDef => ({
  rarity: 'white',
  maxStack: 1,
  valueCopper: 100,
  iconColor: '#cfd8dc',
  iconShape: 'misc',
  ...partial,
});

const blockItem = (
  id: string,
  name: string,
  placesBlock: BlockId,
  iconColor: string,
  rarity: Rarity = 'white',
  valueCopper = 2,
  extra?: Partial<ItemDef>
): ItemDef =>
  item({
    id,
    name,
    category: extra?.category ?? 'block',
    rarity,
    maxStack: 9999,
    valueCopper,
    placesBlock,
    iconColor,
    iconShape: extra?.iconShape ?? 'block',
    ...extra,
  });

const oreItem = (id: string, name: string, placesBlock: BlockId, iconColor: string, rarity: Rarity, valueCopper: number): ItemDef =>
  blockItem(id, name, placesBlock, iconColor, rarity, valueCopper, { category: 'ore', iconShape: 'ore' });

const barItem = (id: string, name: string, iconColor: string, rarity: Rarity, valueCopper: number): ItemDef =>
  item({ id, name, category: 'bar', rarity, maxStack: 9999, valueCopper, iconColor, iconShape: 'bar' });

const matItem = (id: string, name: string, iconColor: string, rarity: Rarity, valueCopper: number, tooltip?: string, shape: ItemDef['iconShape'] = 'misc'): ItemDef =>
  item({ id, name, category: 'material', rarity, maxStack: 9999, valueCopper, iconColor, iconShape: shape, tooltip });

const pickItem = (
  id: string,
  name: string,
  pickPower: number,
  damage: number,
  useTime: number,
  iconColor: string,
  rarity: Rarity,
  valueCopper: number,
  extra?: Partial<ItemDef>
): ItemDef =>
  item({
    id,
    name,
    category: 'tool',
    rarity,
    maxStack: 1,
    valueCopper,
    pickPower,
    toolSpeed: 1 / useTime,
    toolRange: 6,
    weaponType: 'broadsword',
    damage,
    damageType: 'melee',
    knockback: 2,
    useTime,
    autoReuse: true,
    iconColor,
    iconShape: 'pickaxe',
    tooltip: `${pickPower}% pickaxe power`,
    ...extra,
  });

