const armorSet = (
  setId: string,
  setName: string,
  rarity: Rarity,
  baseValue: number,
  color: string,
  accent: string,
  defs: [number, number, number],
  headBonus: EquipmentBonuses,
  bodyBonus: EquipmentBonuses,
  legsBonus: EquipmentBonuses,
  setBonusId: string,
  setBonusDescription: string
): ItemDef[] => [
  item({
    id: `${setId}_helmet`,
    name: `${setName} Helmet`,
    category: 'armor',
    rarity,
    valueCopper: baseValue,
    armorSlot: 'head',
    armorSetId: setId,
    iconColor: color,
    iconAccent: accent,
    iconShape: 'helmet',
    bonuses: { defense: defs[0], ...headBonus, setBonusId, setBonusDescription },
    tooltip: `${defs[0]} defense\nSet Bonus: ${setBonusDescription}`,
  }),
  item({
    id: `${setId}_chestplate`,
    name: `${setName} Chestplate`,
    category: 'armor',
    rarity,
    valueCopper: Math.round(baseValue * 1.4),
    armorSlot: 'body',
    armorSetId: setId,
    iconColor: color,
    iconAccent: accent,
    iconShape: 'chestplate',
    bonuses: { defense: defs[1], ...bodyBonus },
    tooltip: `${defs[1]} defense\nSet Bonus: ${setBonusDescription}`,
  }),
  item({
    id: `${setId}_greaves`,
    name: `${setName} Greaves`,
    category: 'armor',
    rarity,
    valueCopper: Math.round(baseValue * 1.1),
    armorSlot: 'legs',
    armorSetId: setId,
    iconColor: color,
    iconAccent: accent,
    iconShape: 'greaves',
    bonuses: { defense: defs[2], ...legsBonus },
    tooltip: `${defs[2]} defense\nSet Bonus: ${setBonusDescription}`,
  }),
];

