export const ITEMS: Record<string, ItemDef> = {};
for (const it of ITEM_LIST) {
  ITEMS[it.id] = it;
}

export const ALL_ITEMS = ITEM_LIST;

export function getItemDef(id: string): ItemDef | undefined {
  return ITEMS[id];
}

export function getRarityColor(rarity: Rarity): string {
  switch (rarity) {
    case 'gray': return '#828282';
    case 'white': return '#ffffff';
    case 'blue': return '#9696ff';
    case 'green': return '#96ff96';
    case 'orange': return '#ffc896';
    case 'light_red': return '#ff9696';
    case 'pink': return '#ff96ff';
    case 'light_purple': return '#d2a0ff';
    case 'lime': return '#96ff0a';
    case 'yellow': return '#ffff0a';
    case 'cyan': return '#05c8ff';
    case 'red': return '#ff2864';
    case 'purple': return '#b428ff';
    case 'rainbow': return '#ff77cc';
    case 'fiery_red': return '#ff5e1a';
  }
}
